window.AKT.handwriting = [{"title":{"ar":"ثلاثمئة توقيع بخط يده لوليد خيري","en":"Three hundred hand-signed cards for Walid Khairy"},"kind":"signature","year":null,"text":{"ar":"طلب منه القارئ وليد خيري أن يوقّع مجموعة من الكروت ليرسلها إلى قرّاء يطلبون نسخًا موقّعة، فأرسل إليه 300 توقيع بخط يده دون تأخير.","en":"Reader Walid Khairy asked him to sign a batch of cards to send to readers wanting signed copies; he promptly sent back 300 signatures in his own hand."},"url":"https://www.elwatannews.com/news/details/4094440","outlet":{"ar":"الوطن","en":"El Watan"}},{"title":{"ar":"توقيع على ورقة بيضاء لقارئة من طنطا","en":"A signature on a blank sheet for a Tanta reader"},"kind":"signature","year":2016,"text":{"ar":"التقت سارة حاتم به في مؤتمر علمي بطنطا عام 2016 وطلبت توقيعه على استحياء، فوقّع لها على ورقة بيضاء قائلًا «اتفضلي»، وما زالت تحتفظ بها.","en":"Sara Hatem met him at a scientific conference in Tanta in 2016 and shyly asked for his autograph; he signed a blank sheet for her with a simple 'here you go', which she still keeps."},"url":"https://www.elwatannews.com/news/details/6621347","outlet":{"ar":"الوطن","en":"El Watan"}},{"title":{"ar":"«ابق حيًا حتى اللقاء القادم.. اتصرف!» – إهداء «الهول» لتامر نجم","en":"'Stay alive till next time… manage!' – a dedication in Al-Hawl for Tamer Negm"},"kind":"dedication","year":null,"text":{"ar":"في حفل توقيع مجموعته «الهول» بمكتبة ألف في مصر الجديدة طلب منه تامر نجم إهداءً يتمنى له البقاء على قيد الحياة، فكتب: «إلى العزيز تامر نجم.. ابق حيًا حتى اللقاء القادم.. اتصرف!» وذيّله بتوقيعه.","en":"At the signing of his collection Al-Hawl at Alef Bookstore in Heliopolis, Tamer Negm asked for a dedication wishing him to stay alive; he wrote 'To dear Tamer Negm… stay alive till next time… manage!' and signed it."},"url":"https://manassa.news/stories/2967","outlet":{"ar":"المنصة","en":"Al-Manassa"}},{"title":{"ar":"إهداء «بخطه المنمق» إلى «إيمان (ماجي)»","en":"A dedication 'in his neat hand' to 'Eman (Maggie)'"},"kind":"dedication","year":2014,"text":{"ar":"روى محمد الدناصوري أنه وقف أكثر من ساعتين في معرض القاهرة للكتاب قبل رحيله بنحو أربع سنوات ليحصل على إهداء للفتاة التي يحبها، فكتب الإهداء باسم «إيمان (ماجي)» بخطه المنمّق على العدد الأخير من «ما وراء الطبيعة»، وصارت صاحبته زوجته فيما بعد.","en":"Mohamed El-Dennasoury queued over two hours at the Cairo Book Fair about four years before his death for a dedication to the girl he loved; he wrote it to 'Eman (Maggie)' in his neat hand on the last issue of Ma Wara'a al-Tabi'a. She later became El-Dennasoury's wife."},"url":"https://manassa.news/stories/2943","outlet":{"ar":"المنصة","en":"Al-Manassa"}},{"title":{"ar":"نسخة «يوتوبيا» موقّعة لكاتبة المقال","en":"A signed copy of Utopia for the article's writer"},"kind":"dedication","year":2008,"text":{"ar":"يذكر كاتب مقال ArabLit «أحمد خالد توفيق، عبقري» أنه شرّفه بتوقيع روايته «يوتوبيا» في عام صدورها، ولا ينقل نص الإهداء.","en":"The author of ArabLit's 'Ahmed Khaled Tawfik, Genius' recalls being honoured with his signature on Utopia in the year it came out; the wording of the inscription is not given."},"url":"https://arablit.org/2020/11/05/ahmed-khaled-tawfik-genius/","outlet":{"ar":"ArabLit","en":"ArabLit"}},{"title":{"ar":"حفل توقيع «في ممر الفئران» بديوان الزمالك","en":"Signing of In the Rat Path at Diwan Zamalek"},"kind":"dedication","year":2016,"text":{"ar":"إعلان عن حفل توقيع ومناقشة روايته «في ممر الفئران» بمكتبة ديوان فرع الزمالك يوم الخميس 11 أغسطس 2016، حيث وقّع نسخ القرّاء.","en":"Announcement of the signing and discussion of his novel In the Rat Path at Diwan's Zamalek branch on Thursday 11 August 2016, where he signed readers' copies."},"url":"https://www.youm7.com/story/2016/7/20/أحمد-خالد-توفيق-يوقع-روايته-فى-ممر-الفئران-بديوان-الزمالك/2806661","outlet":{"ar":"اليوم السابع","en":"Youm7"}},{"title":{"ar":"«القصاصة ما زالت في جيبي» – عن قصاصاته اليومية «بخط لا يُقرأ»","en":"'The Slip Is Still in My Pocket' – his daily notes 'in an unreadable hand'"},"kind":"note","year":2010,"text":{"ar":"في مقاله بمجلة الشباب (30 سبتمبر 2010) وصف القصاصة المربعة التي يحملها كل صباح، على وجه مهامه وعلى الآخر أفكاره المفاجئة، مكتوبة «بخط لا يُقرأ» حتى عليه هو، ويروي كيف قرأ طبيب امتياز كلمة «المرآة» فيها «المرأة».","en":"In his Al-Shabab column (30 September 2010) he described the square slip he carried each morning, with tasks on one side and sudden ideas on the other, written 'in an unreadable hand' even to him, and how an intern misread 'the mirror' on it as 'the woman'."},"url":"https://insaneyat.com/القصاصة-مازالت-في-جيبي-خالد-توفيق/","outlet":{"ar":"مجلة الشباب (منقول في إنسانيات)","en":"Al-Shabab magazine (via Insaneyat)"}}];
